def countSpecialNumbers(n: int) -> int:
    def count(i: int, m: int) -> int:
        if i == 0:
            return 1
        return (m - i + 1) * count(i - 1, m)

    def dfs(i: int, mask: int) -> int:
        if i >= len(n_str):
            return 1

        cur = ord(n_str[i]) - ord('0')
        if mask & (1 << cur):
            res = dfs(i + 1, mask + (1 << cur))
        else:
            res = 0

        for j in range(0 if i > 0 else 1, cur):
            if not (mask & (1 << j)):
                res += count(len(n_str) - i - 1, 9 - j)

        return res

    n_str = str(n)
    total_sum = 0
    result = dfs(0, 0)

    for i in range(1, len(n_str)):
        total_sum += 9 * count(i - 1, 9)

    return result + total_sum
